sys_ux_macroponent.props:
[
    {
        "defaultValue": "Submissions to Quote Ratio",
        "description": "Title shown above the value.",
        "fieldType": "string",
        "label": "Heading",
        "name": "heading",
        "valueType": "string"
    },
    {
        "defaultValue": "clipboard-outline",
        "description": "Horizon icon for the tile — a full now-icon name ending -outline or -fill (e.g. clipboard-outline, key-fill). Leave empty to hide the icon tile.",
        "fieldType": "icon",
        "label": "Icon",
        "name": "icon",
        "valueType": "string"
    },
    {
        "defaultValue": "info",
        "description": "Theme colour of the icon tile, taken from the theme's alert palette (tint behind, strong colour for the icon). Follows light and dark themes.",
        "fieldType": "choice",
        "label": "Icon tone",
        "name": "iconTone",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Info",
                    "value": "info"
                },
                {
                    "label": "Positive",
                    "value": "positive"
                },
                {
                    "label": "Warning",
                    "value": "warning"
                },
                {
                    "label": "High",
                    "value": "high"
                },
                {
                    "label": "Critical",
                    "value": "critical"
                },
                {
                    "label": "Moderate",
                    "value": "moderate"
                },
                {
                    "label": "Low",
                    "value": "low"
                }
            ],
            "schema": {
                "enum": [
                    "info",
                    "positive",
                    "warning",
                    "high",
                    "critical",
                    "moderate",
                    "low"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": "25",
        "description": "The headline metric. A number or numeric string; formatted per the Value format property.",
        "fieldType": "string",
        "label": "Value",
        "name": "value",
        "valueType": "string"
    },
    {
        "defaultValue": "percent",
        "description": "How the value is rendered.",
        "fieldType": "choice",
        "label": "Value format",
        "name": "format",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Percent (25.00%)",
                    "value": "percent"
                },
                {
                    "label": "Currency ($25.00)",
                    "value": "currency"
                },
                {
                    "label": "Number (25.00)",
                    "value": "number"
                },
                {
                    "label": "None (as typed)",
                    "value": "none"
                }
            ],
            "schema": {
                "enum": [
                    "percent",
                    "currency",
                    "number",
                    "none"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": 2,
        "description": "Decimal places for the value and trend magnitude.",
        "fieldType": "number",
        "label": "Decimal places",
        "name": "decimals",
        "valueType": "string"
    },
    {
        "defaultValue": "$",
        "description": "Prefix used when Value format is Currency.",
        "fieldType": "string",
        "label": "Currency symbol",
        "name": "currencySymbol",
        "valueType": "string"
    },
    {
        "defaultValue": true,
        "description": "Show the trend pill (↑ 12%). Off hides only the pill — the caption (Trend period) still shows. Use it for counts where a percentage means nothing.",
        "fieldType": "boolean",
        "label": "Show trend",
        "name": "showTrend",
        "valueType": "string"
    },
    {
        "defaultValue": "-4.2",
        "description": "Change vs the previous period. The sign sets the arrow (auto); the magnitude is shown in the pill. Empty or not a number → no pill (the caption still shows). To hide the pill regardless, turn off Show trend.",
        "fieldType": "string",
        "label": "Trend value",
        "name": "trendValue",
        "valueType": "string"
    },
    {
        "defaultValue": "auto",
        "description": "Arrow direction. Auto derives it from the sign of the trend value.",
        "fieldType": "choice",
        "label": "Trend direction",
        "name": "trendDirection",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Auto (from sign)",
                    "value": "auto"
                },
                {
                    "label": "Up",
                    "value": "up"
                },
                {
                    "label": "Down",
                    "value": "down"
                },
                {
                    "label": "Flat",
                    "value": "flat"
                }
            ],
            "schema": {
                "enum": [
                    "auto",
                    "up",
                    "down",
                    "flat"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": "MoM",
        "description": "Text beside the pill (MoM, vs yesterday) — or, with the pill hidden, a caption under the value (Card + phone). Shown whenever it is set.",
        "fieldType": "string",
        "label": "Trend period / caption",
        "name": "trendPeriod",
        "valueType": "string"
    },
    {
        "defaultValue": true,
        "description": "When on, an upward trend uses the positive colour and downward the critical colour. Turn off for lower-is-better metrics (cost, churn, latency).",
        "fieldType": "boolean",
        "label": "Increase is positive",
        "name": "trendPositiveIsGood",
        "valueType": "string"
    },
    {
        "defaultValue": "center",
        "description": "How the icon tile aligns vertically against the heading/value/trend block.",
        "fieldType": "choice",
        "label": "Icon vertical alignment",
        "name": "iconAlign",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Top",
                    "value": "top"
                },
                {
                    "label": "Center",
                    "value": "center"
                },
                {
                    "label": "Bottom",
                    "value": "bottom"
                }
            ],
            "schema": {
                "enum": [
                    "top",
                    "center",
                    "bottom"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": false,
        "description": "When on, the card is focusable and emits a 'Metric card clicked' event.",
        "fieldType": "boolean",
        "label": "Clickable",
        "name": "clickable",
        "valueType": "string"
    }
]
